    slug text,
    name text,
    "stateCode" text,
    "stateName" text,
    country text,
    "macroRegion" text,
    latitude numeric,
    longitude numeric,
    "ibgeCode" text,
    "isCapital" boolean,
    rank int,
    "familyScore" int,
    "destinationType" text,
    "curationLevel" text,
    "recommendationReadiness" text,
    "minimumFamilyRequirementsPassed" boolean,
    "idealAges" text[],
    "travelModes" text[],
    "bestFor" text,
    "attentionPoints" text[],
    tags text[],
    source jsonb
  )
), upsert_catalog as (
  insert into public.family_destination_catalog_1001 (
    slug, name, state_code, state_name, country, macro_region, latitude, longitude,
    ibge_code, is_capital, rank, family_score, destination_type, curation_level,
    recommendation_readiness, minimum_family_requirements_passed, tags, ideal_ages,
    travel_modes, best_for, attention_points, source, updated_at
  )
  select slug, name, "stateCode", "stateName", country, "macroRegion", latitude, longitude,
    "ibgeCode", "isCapital", rank, "familyScore", "destinationType", "curationLevel",
    "recommendationReadiness", "minimumFamilyRequirementsPassed", tags, "idealAges",
    "travelModes", "bestFor", "attentionPoints", source, now()
  from payload
  on conflict (slug) do update set
    name = excluded.name,
    state_code = excluded.state_code,
    state_name = excluded.state_name,
    country = excluded.country,
    macro_region = excluded.macro_region,
    latitude = excluded.latitude,
    longitude = excluded.longitude,
    ibge_code = excluded.ibge_code,
    is_capital = excluded.is_capital,
    rank = excluded.rank,
    family_score = excluded.family_score,
    destination_type = excluded.destination_type,
    curation_level = excluded.curation_level,
    recommendation_readiness = excluded.recommendation_readiness,
    minimum_family_requirements_passed = excluded.minimum_family_requirements_passed,
    tags = excluded.tags,
    ideal_ages = excluded.ideal_ages,
    travel_modes = excluded.travel_modes,
    best_for = excluded.best_for,
    attention_points = excluded.attention_points,
    source = excluded.source,
    updated_at = now()
  returning slug
)
insert into public.destinations (slug, name, state, country, latitude, longitude, source, curated_data, ai_calculated_data, updated_at)
select
  slug,
  name,
  "stateCode",
  'BR',
  latitude,
  longitude,
  'family_destination_catalog_1001',
  jsonb_build_object(
    'stateName', "stateName",
    'macroRegion', "macroRegion",
    'ibgeCode', "ibgeCode",
    'isCapital', "isCapital",
    'curationLevel', "curationLevel",
    'recommendationReadiness', "recommendationReadiness",
    'minimumFamilyRequirementsPassed', "minimumFamilyRequirementsPassed",
    'tags', tags,
    'idealAges', "idealAges",
    'travelModes', "travelModes",
    'bestFor', "bestFor",
    'attentionPoints', "attentionPoints",
    'source', source
  ),
  jsonb_build_object(
    'familyScore', "familyScore",
    'destinationType', "destinationType",
    'catalogRank', rank
  ),
  now()
from payload
on conflict (slug) do update set
  name = excluded.name,
  state = excluded.state,
  country = excluded.country,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  source = excluded.source,
  curated_data = coalesce(public.destinations.curated_data, '{}'::jsonb) || excluded.curated_data,
  ai_calculated_data = coalesce(public.destinations.ai_calculated_data, '{}'::jsonb) || excluded.ai_calculated_data,
  updated_at = now();

create index if not exists idx_family_destination_catalog_1001_score on public.family_destination_catalog_1001(family_score desc, rank asc);
create index if not exists idx_family_destination_catalog_1001_state on public.family_destination_catalog_1001(state_code, destination_type);

alter table public.family_destination_catalog_1001 enable row level security;
do $$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'family_destination_catalog_1001' and policyname = 'family_destination_catalog_1001_read_public'
  ) then
    create policy family_destination_catalog_1001_read_public
      on public.family_destination_catalog_1001 for select
      using (true);
  end if;
end $$;

grant select on public.family_destination_catalog_1001 to anon, authenticated;
